mapper.select:
SELECT rp.*, u.real_name as inventor_name, p.project_name FROM research_patent rp LEFT JOIN sys_user u ON rp.inventor_id = u.id LEFT JOIN research_project p ON rp.project_id = p.id WHERE rp.deleted = 0
AND (rp.patent_name LIKE CONCAT('%',#{keyword},'%') OR rp.patent_no LIKE CONCAT('%',#{keyword},'%'))
AND rp.status = #{status}
AND rp.inventor_id = #{inventorId}
ORDER BY rp.create_time DESC
